function IdolLive3D_UITouchTipsCell:Init( key_, name_, isTouched_ )

    self.ImgBgNor  = self.controller.transform:Find("ImgBgNor")

    CfUtils.SetActive( self.controller.gameObject, true )

    self.key = key_
    self.name = tostring(name_) 
    CfUtils.FillText( self.Txttitle, self.name )

    self.cachedIsTouched = (isTouched_==true)
    self:SwitchState( isTouched_ )
end




