    self:Delete()
end


----------------------------------------------------------


function IdolLive3D_UITouchTipsCell:SwitchState( isTouched_ )

    if isTouched_ == true then 
        -- 第一次触发本动作: 
        if self.cachedIsTouched == false then 
            self.cachedIsTouched = true
            print("第一次触发 动作: " .. tostring(self.key))
            Events.Broadcast(IdolLive3D_States.EventFirstActiveUITouchTip, self.key )
        end 
        ---
        KTool.SetActive(self.ImgBg, true)--白条
        KTool.SetActive( self.ImgBgNor, false )
        CfUtils.SetUISwitchImage(self.ImgIcon.gameObject, 1)-- 红色ui
        KTool.SetActive( self.ImgIcon.gameObject, true )
        CfUtils.FillText( self.Txttitle, self.name )
    else 
        KTool.SetActive(self.ImgBg, false)--黑条
        KTool.SetActive( self.ImgBgNor, true )
        CfUtils.SetUISwitchImage(self.ImgIcon.gameObject, 2)-- 灰色ui
        KTool.SetActive( self.ImgIcon.gameObject, false )
        CfUtils.FillText( self.Txttitle, "" )
    end 

end







return IdolLive3D_UITouchTipsCell
